// @ts-check

import { readFileSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { fileURLToPath } from "node:url";

const rootDir = dirname(dirname(fileURLToPath(import.meta.url)));
const sourcePath = `${rootDir}/packages/html/styles.css`;
const outputPath = `${rootDir}/packages/html/src/default_styles.js`;

const styles = readFileSync(sourcePath, "utf8");
const generated = [
  "// @ts-nocheck",
  "// Generated by scripts/sync-html-default-styles.js.",
  "// Update packages/html/styles.css and rerun `bun run sync:html-styles`.",
  `export const DEFAULT_STYLES = ${JSON.stringify(styles)};`,
  "",
].join("\n");

writeFileSync(outputPath, generated);
